head.script:
scwin.screenId = "jldinf10107";

///////// 1. 변수 및 선언 영역 /////////

scwin.init_line = 1;

scwin.redmpt_line = 0;

scwin.putLine = 0;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_optionType", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("optionType"))); } },
        { childId: "ipt_callLine", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("callLine"))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

        if( '' + dma_pageContext.get("redmpt_line") + '' === "" || '' + dma_pageContext.get("redmpt_line") + '' === "0" ){
            for(var i = 0 ; i < scwin.init_line ; i++){
                scwin.addRow(i+1);
                scwin.redmpt_line ++;
            }
        }else{
            scwin.redmpt_line = '' + dma_pageContext.get("redmpt_line") + '' === "" ? 0 : Number("" + dma_pageContext.get("redmpt_line") + "");
            for(var i = 0 ; i < scwin.redmpt_line ; i++){
                scwin.addRow(i+1);
            }
        }

        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10107.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf10107.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_AddRow_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_AddRow_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_AddRow_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.addRow()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10107.btn_AddRow_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_DelRow_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_DelRow_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_DelRow_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.delRow()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10107.btn_DelRow_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_sendForm_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_sendForm_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_sendForm_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.send_form('__self.form')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf10107.btn_sendForm_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_sendCancel_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_sendCancel_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_sendCancel_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.send_cancel()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10107.btn_sendCancel_onclick' }); }
};

/**
 * @event
 * @name scwin.table_13_oneditend
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex value
 * @returns
 * @hidden N
*/
scwin.table_13_oneditend = function (rowIndex, columnIndex, value) {  };


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.addRow
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.addRow = function () { const d = $c.util.getComponent('dlt_call'); if (d && d.insertRow) { d.insertRow(); } };


/**
 * @method
 * @name scwin.delRow
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.delRow = function () {
    /* sdd-asis-lifecycle:begin fn_DelRow — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (scwin.redmpt_line > 0) {
        $("#tr_call_" + scwin.redmpt_line).remove();
        scwin.redmpt_line--;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.send_form
 * @author Inswave
 * @date 2026. 09. 29
 * @param fm
 * @returns
 * @hidden N
*/
scwin.send_form = async function (fm) {
    /* sdd-asis-lifecycle:begin send_form — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).div_redmpt).innerHTML = "";
    if (scwin.redmpt_line > 0) {
        for (var i = 0; i < scwin.redmpt_line; i++) {
            if ($c.str.getByteLength($("#int_pay_dd" + (i + 1)).val()) == 0) {
                await $c.win.alert("이자지급일을 입력하세요.");
                console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
            if ($c.str.getByteLength($("#redmpt_amt" + (i + 1)).val()) == 0) {
                await $c.win.alert("상환금액을 입력하세요.");
                console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
            if ($c.str.getByteLength($("#coupn_rt" + (i + 1)).val()) == 0) {
                await $c.win.alert("이자율을 입력하세요.");
                console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
            if ($c.str.getByteLength($("#redmpt_pd_int_tp_cd" + (i + 1)).val()) == 0) {
                await $c.win.alert("거치기간이자를 입력하세요.");
                console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        }
    } else {
        await $c.win.alert("불균등 상세내역을 입력하세요.");
        return;
    }
    (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("redmpt_line")) && ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("redmpt_line")).setValue ? ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("redmpt_line")).setValue(scwin.redmpt_line) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "redmpt_line"), void (scwin.redmpt_line)));
    let htmlStr = "";
    for (var i = 0; i < scwin.redmpt_line; i++) {
        const int_pay_dd = $("#int_pay_dd" + (i + 1)).val();
        const redmpt_amt = $("#redmpt_amt" + (i + 1)).val();
        const coupn_rt = $("#coupn_rt" + (i + 1)).val();
        const redmpt_pd_int_tp_cd = $("#redmpt_pd_int_tp_cd" + (i + 1)).val();
        htmlStr += "<input type='hidden' name='int_pay_dd' id='int_pay_dd" + (i + 1) + "' value='" + int_pay_dd + "' />";
        htmlStr += "<input type='hidden' name='redmpt_amt' id='redmpt_amt" + (i + 1) + "' value='" + redmpt_amt + "' />";
        htmlStr += "<input type='hidden' name='redmpt_coupn_rt_list' id='redmpt_coupn_rt_list" + (i + 1) + "' value='" + coupn_rt + "' />";
        htmlStr += "<input type='hidden' name='redmpt_pd_int_tp_cd_list' id='redmpt_pd_int_tp_cd_list" + (i + 1) + "' value='" + redmpt_pd_int_tp_cd + "' /></br>";
    }
    opener.$("#div_redmpt").append(htmlStr);
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.send_cancel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.send_cancel = function () {
    /* sdd-asis-lifecycle:begin send_cancel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
